import{useEffect,useRef,useState}from"react";import{Routes,Route,Navigate,NavLink,useNavigate,useParams,useLocation}from"react-router-dom";import{LayoutDashboard,BookOpen,History,Users,LogOut,Plus,Clock,CheckCircle2,Menu,X,GraduationCap,ChevronRight,Download,Upload,Settings,Activity,ShieldAlert,Eye,EyeOff}from"lucide-react";
const API=import.meta.env.PROD?"/api":(import.meta.env.VITE_API_URL||"http://localhost:5000/api");
