function ToastHost(){let[items,setItems]=useState([]);useEffect(()=>{let receive=e=>{let id=Date.now()+Math.random(),item={id,...e.detail};setItems(current=>[...current,item]);setTimeout(()=>setItems(current=>current.filter(x=>x.id!==id)),4000)};window.addEventListener("app-toast",receive);return()=>window.removeEventListener("app-toast",receive)},[]);return <><ExamSecurityMonitor/><ReactivationHost/><div className="toast-stack" aria-live="polite">{items.map(item=><div key={item.id} className={`toast ${item.type}`}><CheckCircle2/><span>{item.message}</span><button onClick={()=>setItems(current=>current.filter(x=>x.id!==item.id))}><X/></button></div>)}</div></>}
const authRole=p=>p.startsWith("/admin")?"admin":p.startsWith("/student")?"student":null,authToken=role=>localStorage.getItem(`token_${role}`)||localStorage.token;
const localDateTime=value=>{let date=new Date(value),offset=date.getTimezoneOffset()*60000;return new Date(date-offset).toISOString().slice(0,16)},requestReactivation=()=>new Promise(resolve=>window.dispatchEvent(new CustomEvent("reactivate-exam",{detail:{resolve}})));
function ReactivationHost(){let[request,setRequest]=useState(null),[start,setStart]=useState(""),[end,setEnd]=useState(""),[error,setError]=useState("");useEffect(()=>{let open=e=>{setStart(localDateTime(Date.now()));setEnd(localDateTime(Date.now()+7*86400000));setError("");setRequest(e.detail)};window.addEventListener("reactivate-exam",open);return()=>window.removeEventListener("reactivate-exam",open)},[]);if(!request)return null;let close=value=>{request.resolve(value);setRequest(null)},submit=e=>{e.preventDefault();if(!start||!end)return setError("Choose both start and end times.");if(new Date(end)<=new Date(start))return setError("End time must be later than start time.");if(new Date(end)<=new Date())return setError("End time must be in the future.");close(JSON.stringify({start_at:start,end_at:end}))};return <div className="modal-backdrop" role="presentation" onMouseDown={e=>e.target===e.currentTarget&&close(null)}><form className="reactivate-modal" onSubmit={submit} role="dialog" aria-modal="true" aria-labelledby="reactivate-title"><div className="modal-icon"><Clock/></div><button type="button" className="modal-close" aria-label="Close" onClick={()=>close(null)}><X/></button><small>EXAM SCHEDULE</small><h2 id="reactivate-title">Reactivate exam</h2><p>Select the new availability window for eligible students.</p>{error&&<div className="error">{error}</div>}<label>Start time<input required type="datetime-local" value={start} onChange={e=>{setStart(e.target.value);setError("")}}/></label><label>End time<input required type="datetime-local" value={end} min={start} onChange={e=>{setEnd(e.target.value);setError("")}}/></label><div className="modal-actions"><button type="button" className="btn soft" onClick={()=>close(null)}>Cancel</button><button className="btn">Reactivate exam</button></div></form></div>}
const api=async(p,o={})=>{if(p.endsWith("/reactivate")&&o.body==="{}"){let body=await requestReactivation();if(!body)throw Error("Reactivation cancelled");o={...o,body}}let role=authRole(p),t=role?authToken(role):localStorage.token,r=await fetch(API+p,{...o,headers:{"Content-Type":"application/json",...(t?{Authorization:`Bearer ${t}`}:{})}}),j=await r.json();if(!r.ok){if((j.message==="Forbidden"||r.status===401)&&t&&role){localStorage.removeItem(`token_${role}`);localStorage.removeItem(`user_${role}`);if(location.pathname.startsWith(`/${role}`))window.location.replace(`/login/${role}`)}throw Error(j.message)}return j.data};
function ExamSecurityMonitor(){let location=useLocation(),nav=useNavigate(),[state,setState]=useState(null),match=location.pathname.match(/^\/student\/exams\/(\d+)$/),examId=match?.[1],session=useRef(sessionStorage.exam_session_id||(sessionStorage.exam_session_id=crypto.randomUUID())),lastWarning=useRef();useEffect(()=>{if(!examId){setState(null);return}let stopped=false,timer;let report=async event_type=>{if(!state?.attempt_id)return;try{let result=await api(`/student/attempts/${state.attempt_id}/events`,{method:"POST",body:JSON.stringify({event_type})});if(result.action==="WARNING")toast(result.message,"warning");if(result.action==="TERMINATED"){toast("Your exam was auto-submitted.","warning");nav(`/student/terminated/${result.attempt_id}`,{replace:true})}}catch(error){if(!error.message.includes("not active"))toast(error.message)}},visibility=()=>document.hidden&&report("TAB_HIDDEN"),fullscreen=()=>!document.fullscreenElement&&report("FULLSCREEN_EXIT"),copy=()=>report("COPY"),paste=()=>report("PASTE"),menu=()=>report("CONTEXT_MENU");let heartbeat=async()=>{try{let active=state||await api(`/student/exams/${examId}/active-attempt`);if(!active||stopped)return;setState(active);let next=await api(`/student/attempts/${active.attempt_id}/heartbeat`,{method:"POST",body:JSON.stringify({session_id:session.current})});setState({...active,...next});if(next.warning&&next.warning!==lastWarning.current){lastWarning.current=next.warning;toast(next.warning,"warning")}if(next.completed)nav(`/student/results/${next.result_id}`,{replace:true});if(next.status==="TERMINATED")nav(`/student/terminated/${active.attempt_id}`,{replace:true})}catch(e){if(!stopped&&e.message.includes("another browser session")){toast(e.message);nav("/student/exams",{replace:true})}}};document.addEventListener("visibilitychange",visibility);document.addEventListener("fullscreenchange",fullscreen);document.addEventListener("copy",copy);document.addEventListener("paste",paste);document.addEventListener("contextmenu",menu);heartbeat();timer=setInterval(heartbeat,30000);if(performance.getEntriesByType("navigation")[0]?.type==="reload")setTimeout(()=>report("REFRESH"),1000);return()=>{stopped=true;clearInterval(timer);document.removeEventListener("visibilitychange",visibility);document.removeEventListener("fullscreenchange",fullscreen);document.removeEventListener("copy",copy);document.removeEventListener("paste",paste);document.removeEventListener("contextmenu",menu)}},[examId,state?.attempt_id,nav]);useEffect(()=>{if(state?.status==="TERMINATED"&&state.attempt_id)nav(`/student/terminated/${state.attempt_id}`,{replace:true})},[state?.status,state?.attempt_id,nav]);if(!state||!examId)return null;if(state.status==="PAUSED")return <div className="exam-blocker"><ShieldAlert/><h2>Exam paused</h2><p>Your administrator has paused this attempt. Keep this page open.</p></div>;if(state.status==="TERMINATED")return null;return null}
