const Badge=({children})=><span className={`badge ${String(children).toLowerCase()}`}>{children}</span>,Card=({children,className=""})=><section className={`card ${className}`}>{children}</section>,Btn=({children,kind="",...p})=><button className={`btn ${kind}`} {...p}>{children}</button>;
