function ForgotPassword(){let nav=useNavigate(),[email,setEmail]=useState(""),[sent,setSent]=useState(false),[busy,setBusy]=useState(false);let submit=async e=>{e.preventDefault();setBusy(true);try{await api("/auth/forgot-password",{method:"POST",body:JSON.stringify({email})});setSent(true)}catch(error){toast(error.message)}finally{setBusy(false)}};return <main className="login auth-single"><form onSubmit={submit}><small>ACCOUNT RECOVERY</small><h2>Reset your password</h2>{sent?<><div className="success-message">If the address is registered, a reset link has been sent.</div><Btn type="button" onClick={()=>nav("/login/student")}>Return to sign in</Btn></>:<><p>Enter the email address connected to your account.</p><label>Email<input required type="email" autoComplete="email" value={email} onChange={e=>setEmail(e.target.value)}/></label><Btn disabled={busy}>{busy?"Sending…":"Send reset link"}</Btn><button type="button" className="link" onClick={()=>nav("/login/student")}>Return to sign in</button></>}</form></main>}
