function Shell({role,title,action,children}){let nav=useNavigate(),u=JSON.parse(localStorage.getItem(`user_${role}`)||localStorage.user||"null"),[open,setOpen]=useState(false);if(!u||u.role!==role.toUpperCase())return <Navigate to={`/login/${role}`}/>;return <div className="shell" style={{"--brand":u.institute?.primary_color||"#4169e1"}}><aside className={open?"open":""}><div className="logo"><GraduationCap/><b>{u.institute?.name||"Axiom"}<small>EXAM PORTAL</small></b><button onClick={()=>setOpen(false)}><X/></button></div><nav>{menus[role].map(([p,I,n])=><NavLink key={p} end={p==`/${role}`} to={p}><I/>{n}</NavLink>)}</nav><div className="account"><i>{u.name[0]}</i><b>{u.name}<small>{role}</small></b><button onClick={()=>{localStorage.removeItem(`token_${role}`);localStorage.removeItem(`user_${role}`);nav(`/login/${role}`)}}><LogOut/></button></div></aside><main className="content"><header><button className="hamb" onClick={()=>setOpen(true)}><Menu/></button><div><small>{u.institute?.name||role+" workspace"}</small><h1>{title}</h1></div>{action}</header>{children}</main></div>}
