function AdminHome(){let[d]=useLoad("/admin/dashboard"),nav=useNavigate();if(!d)return <Shell role="admin" title="Overview"><Loading/></Shell>;let s=d.stats;return <Shell role="admin" title="Overview"><div className="welcome"><div><small>ASSESSMENT CONTROL CENTER</small><h2>Good morning, Administrator.</h2><p>Here’s what’s happening across your program.</p></div><Btn onClick={()=>nav("/admin/exams/new")}><Plus/> Create exam</Btn></div><div className="stats"><Stat n="Students online" v={s.students_online}/><Stat n="Active attempts" v={s.active_attempts}/><Stat n="Completion rate" v={`${s.completion_rate}%`}/><Stat n="Pass rate" v={`${s.pass_rate}%`}/><Stat n="Average score" v={`${s.average_score}%`}/><Stat n="Abandoned" v={s.abandoned}/></div><div className="twocol"><Card><h3>Performance snapshot</h3><div className="score"><strong>{s.average_score}%</strong><span>Program average</span></div><p>Passed <b>{s.passed}</b></p><p>Needs support <b>{d.students_needing_support.length}</b></p><p>API / database <b>{d.health.api} / {d.health.database}</b></p><p>Student usage <b>{d.warnings.student_usage}%</b> · Exam usage <b>{d.warnings.exam_usage}%</b></p></Card><Card><h3>Recent attempts</h3>{d.recent_attempts.length?d.recent_attempts.map(a=><div className="row" key={a.id}><i>{a.student[0]}</i><span><b>{a.student}</b><small>{a.exam_name}</small></span><strong>{a.percentage}%</strong><Badge>{a.result}</Badge></div>):<Empty/>}</Card></div>{d.unusual_failure_rates.length>0&&<Card><h3>Unusual failure rates</h3>{d.unusual_failure_rates.map(item=><div className="row" key={item.exam_id}><span><b>{item.exam}</b><small>{item.attempts} completed attempts</small></span><strong>{item.failure_rate}% failed</strong></div>)}</Card>}</Shell>}
function AdminExams(){let[d,reload]=useLoad("/admin/exams"),nav=useNavigate(),file=useRef(),[busy,setBusy]=useState(false);let act=async(x,a)=>{if(a==="delete"&&!confirm("Archive this exam?"))return;try{await api(`/admin/exams/${x}${a==="delete"?"":`/${a}`}`,{method:a==="delete"?"DELETE":"POST",body:"{}"});toast(a==="delete"?"Exam archived":a==="publish"?"Exam published":a==="complete"?"Exam completed":"Exam reactivated","success");reload()}catch(e){toast(e.message)}};let examLink=x=>`${window.location.origin}/exam/${x.access_code}`,copy=async x=>{try{await navigator.clipboard.writeText(examLink(x));toast(`Link copied. Exam code: ${x.access_code}`,"success")}catch(e){toast("Could not copy the exam link")}},whatsapp=x=>{toast("Opening WhatsApp share","success");window.open(`https://wa.me/?text=${encodeURIComponent(`Exam: ${x.title}\nCode: ${x.access_code}\nLink: ${examLink(x)}`)}`,"_blank","noopener,noreferrer")};let download=async()=>{let r=await fetch(API+"/admin/exams/import-template",{headers:{Authorization:`Bearer ${localStorage.token}`}});if(!r.ok){let j=await r.json();return toast(j.message)}let blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="exam_import_template.xlsx";a.click();URL.revokeObjectURL(url);toast("Excel template downloaded","success")};let upload=async e=>{let selected=e.target.files[0];if(!selected)return;setBusy(true);try{let body=new FormData();body.append("file",selected);let r=await fetch(API+"/admin/exams/import",{method:"POST",headers:{Authorization:`Bearer ${localStorage.token}`},body}),j=await r.json();if(!r.ok)throw Error(j.message);toast(j.message,"success");reload()}catch(error){toast(error.message)}finally{setBusy(false);e.target.value=""}};let actions=<div className="exam-actions"><Btn kind="soft" onClick={download}><Download/> Excel template</Btn><Btn kind="soft" disabled={busy} onClick={()=>file.current.click()}><Upload/> {busy?"Uploading…":"Upload Excel"}</Btn><input ref={file} type="file" accept=".xlsx" hidden onChange={upload}/><Btn onClick={()=>nav("/admin/exams/new")}><Plus/> Create exam</Btn></div>;return <Shell role="admin" title="Exam management" action={actions}>{!d?<Loading/>:<><Card className="import-help"><b>Create exams from Excel</b><span>Download the template, keep its columns, add one question per row, then upload it. Imported exams are saved as drafts.</span></Card><div className="exam-list-head"><h3>All exams <small>{d.length} total</small></h3></div><div className="admin-exam-grid">{d.map(x=><Card className={`admin-exam-card exam-${x.status.toLowerCase()}`} key={x.id}><div className="exam-card-top"><div className="exam-card-icon"><BookOpen/></div><Badge>{x.status}</Badge></div><h2>{x.title}</h2><p>{x.description||"No description provided."}</p><div className="exam-code"><span>EXAM CODE</span><strong>{x.access_code}</strong></div><div className="exam-card-details"><span><small>Category</small><b>{x.exam_category}</b></span><span><small>Audience</small><b>{x.target_category}</b></span><span><small>Questions</small><b>{x.questions}</b></span><span><small>Duration</small><b>{x.duration} min</b></span></div><div className="exam-card-schedule"><Clock/><span><small>Exam window</small><b>{fmt(x.start_at)} — {fmt(x.end_at)}</b></span></div><div className="exam-card-actions"><Btn kind="soft" onClick={()=>copy(x)}>Copy link</Btn><Btn kind="soft" onClick={()=>whatsapp(x)}>WhatsApp</Btn><Btn kind="soft" onClick={()=>nav(`/admin/exams/${x.id}/report`)}>Results</Btn><Btn kind="soft" onClick={()=>nav(`/admin/exams/${x.id}/edit`)}>Edit</Btn>{x.status==="DRAFT"&&<Btn onClick={()=>act(x.id,"publish")}>Publish</Btn>}{x.status==="PUBLISHED"&&<Btn onClick={()=>act(x.id,"complete")}>Complete</Btn>}{x.status==="COMPLETED"&&<Btn onClick={()=>act(x.id,"reactivate")}>Reactivate</Btn>}<button className="danger" onClick={()=>act(x.id,"delete")}>Archive</button></div></Card>)}</div></>}</Shell>}
function NewExam(){let{id}=useParams(),nav=useNavigate(),[cats]=useLoad("/admin/categories"),[students]=useLoad("/admin/students"),[step,setStep]=useState(1),[f,setF]=useState({title:"",description:"",exam_category:"Technical",audience_mode:"category",student_category_id:"",assigned_student_ids:[],duration:30,total_marks:10,passing_percentage:50,start_at:"",end_at:"",questions:[{text:"",type:"SINGLE",marks:10,options:[{text:"",correct:true},{text:"",correct:false}]}]});useEffect(()=>{if(id)api(`/admin/exams/${id}`).then(x=>setF({...x,start_at:x.start_at?.slice(0,16)||"",end_at:x.end_at?.slice(0,16)||"",questions:x.question_list.map(q=>({text:q.text,type:q.type,marks:q.marks,correct_answer:q.correct_answer||"",options:q.options.map(o=>({text:o.text,correct:o.correct}))}))})).catch(e=>toast(e.message))},[id]);let set=(k,v)=>setF({...f,[k]:v}),save=async()=>{try{await api(id?`/admin/exams/${id}`:"/admin/exams",{method:id?"PUT":"POST",body:JSON.stringify(f)});toast(id?"Exam updated successfully":"Exam created successfully","success");nav("/admin/exams")}catch(e){toast(e.message)}};return <Shell role="admin" title={id?"Edit exam":"Create exam"}><div className="steps">{["Basics","Schedule","Question","Review"].map((x,i)=><span className={step>=i+1?"active":""}><i>{i+1}</i>{x}</span>)}</div><Card className="form"><small>STEP {step} OF 4</small>{step===1&&<><h2>Set the foundation.</h2><label>Exam title<input value={f.title} onChange={e=>set("title",e.target.value)}/></label><label>Description<textarea value={f.description} onChange={e=>set("description",e.target.value)}/></label><div className="cols"><label>Category<input value={f.exam_category} onChange={e=>set("exam_category",e.target.value)}/></label><label>Assign exam to<select value={f.audience_mode} onChange={e=>setF({...f,audience_mode:e.target.value,student_category_id:"",assigned_student_ids:[]})}><option value="category">Student type</option><option value="students">Selected students</option></select></label></div>{f.audience_mode==="category"?<label>Student type<select required value={f.student_category_id||""} onChange={e=>set("student_category_id",Number(e.target.value)||"")}><option value="">Select a student type</option>{cats?.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label>:<label>Students<select className="student-picker" multiple required value={f.assigned_student_ids||[]} onChange={e=>set("assigned_student_ids",[...e.target.selectedOptions].map(option=>Number(option.value)))}>{students?.filter(s=>s.status==="ACTIVE").map(s=><option key={s.id} value={s.id}>{s.name} · {s.student_id} · {s.category}</option>)}</select><small>Hold Ctrl (Windows) or Command (Mac) to select more than one student.</small></label>}<div className="cols"><label>Duration (min)<input type="number" value={f.duration} onChange={e=>set("duration",+e.target.value)}/></label><label>Pass percentage<input type="number" value={f.passing_percentage} onChange={e=>set("passing_percentage",+e.target.value)}/></label></div></>}{step===2&&<><h2>Choose the exam window.</h2><label>Starts<input type="datetime-local" value={f.start_at} onChange={e=>set("start_at",e.target.value)}/></label><label>Ends<input type="datetime-local" value={f.end_at} onChange={e=>set("end_at",e.target.value)}/></label></>}{step===3&&<Question f={f} setF={setF}/>} {step===4&&<><h2>Ready for review.</h2><dl><div><dt>Exam</dt><dd>{f.title}</dd></div><div><dt>Audience</dt><dd>{f.audience_mode==="students"?`${f.assigned_student_ids.length} selected student(s)`:cats?.find(c=>c.id===f.student_category_id)?.name||"Not selected"}</dd></div><div><dt>Duration</dt><dd>{f.duration} minutes</dd></div><div><dt>Marks</dt><dd>{f.total_marks}</dd></div><div><dt>Status</dt><dd>DRAFT</dd></div></dl><p>You can publish it after saving.</p></>}<footer>{step>1&&<Btn kind="soft" onClick={()=>setStep(step-1)}>Previous</Btn>}<span/>{step<4?<Btn onClick={()=>setStep(step+1)}>Continue</Btn>:<Btn onClick={save}>{id?"Save changes":"Save draft"}</Btn>}</footer></Card></Shell>}
function Question({f,setF}){const blank=()=>({text:"",type:"SINGLE",marks:1,correct_answer:"true",options:[{text:"",correct:true},{text:"",correct:false}]});const update=(qi,patch)=>{const questions=f.questions.map((q,i)=>i===qi?{...q,...patch}:q);setF({...f,questions,total_marks:questions.reduce((n,q)=>n+(Number(q.marks)||0),0)})};const changeType=(qi,type)=>update(qi,{type,correct_answer:type==="TRUE_FALSE"?"true":"",options:type==="SINGLE"||type==="MULTIPLE"?[{text:"",correct:true},{text:"",correct:false}]:[]});const updateOption=(qi,oi,patch)=>{let options=f.questions[qi].options.map((o,i)=>i===oi?{...o,...patch}:o);if(patch.correct&&f.questions[qi].type==="SINGLE")options=options.map((o,i)=>({...o,correct:i===oi}));update(qi,{options})};const addOption=qi=>update(qi,{options:[...f.questions[qi].options,{text:"",correct:false}]});const removeQuestion=qi=>{const questions=f.questions.filter((_,i)=>i!==qi);setF({...f,questions:questions.length?questions:[blank()],total_marks:questions.reduce((n,q)=>n+(Number(q.marks)||0),0)})};return <><div className="question-builder-head"><div><h2>Build the question paper.</h2><p>Use any supported question type and set its answer key.</p></div><Btn kind="soft" type="button" onClick={()=>setF({...f,questions:[...f.questions,blank()]})}><Plus/> Add question</Btn></div>{f.questions.map((q,qi)=><div className="question-editor" key={qi}><div className="question-title"><strong>Question {qi+1}</strong>{f.questions.length>1&&<button type="button" className="danger" onClick={()=>removeQuestion(qi)}>Remove</button>}</div><div className="cols"><label>Question type<select value={q.type} onChange={e=>changeType(qi,e.target.value)}><option value="SINGLE">MCQ — single answer</option><option value="MULTIPLE">Checkbox — multiple answers</option><option value="TRUE_FALSE">True / False</option><option value="SHORT_ANSWER">Short answer</option><option value="PARAGRAPH">Paragraph answer</option></select></label><label>Marks<input type="number" min="0.5" step="0.5" value={q.marks} onChange={e=>update(qi,{marks:+e.target.value})}/></label></div><label>Question<textarea value={q.text} onChange={e=>update(qi,{text:e.target.value})} placeholder="Enter the question"/></label>{(q.type==="SINGLE"||q.type==="MULTIPLE")&&<div className="answer-options"><span>Select {q.type==="MULTIPLE"?"all correct answers":"the correct answer"}</span>{q.options.map((o,oi)=><label className="option" key={oi}><input type={q.type==="MULTIPLE"?"checkbox":"radio"} name={`correct-${qi}`} checked={o.correct} onChange={e=>updateOption(qi,oi,{correct:e.target.checked})}/><input value={o.text} onChange={e=>updateOption(qi,oi,{text:e.target.value})} placeholder={`Option ${oi+1}`}/></label>)}<button type="button" className="link add-option" onClick={()=>addOption(qi)}>+ Add option</button></div>}{q.type==="TRUE_FALSE"&&<label>Correct answer<select value={q.correct_answer} onChange={e=>update(qi,{correct_answer:e.target.value})}><option value="true">True</option><option value="false">False</option></select></label>}{(q.type==="SHORT_ANSWER"||q.type==="PARAGRAPH")&&<label>Accepted answer{q.type==="PARAGRAPH"?<textarea value={q.correct_answer||""} onChange={e=>update(qi,{correct_answer:e.target.value})} placeholder="Enter the model answer used for automatic grading"/>:<input value={q.correct_answer||""} onChange={e=>update(qi,{correct_answer:e.target.value})} placeholder="Enter the accepted answer"/>}<small>Answers are matched without case differences or surrounding spaces.</small></label>}</div>)}</>}
function ExamLink(){let{code}=useParams(),nav=useNavigate(),[error,setError]=useState("");useEffect(()=>{let user=JSON.parse(localStorage.user||"null");if(!user||user.role!=="STUDENT"){localStorage.pending_exam_code=code.toUpperCase();nav("/login/student",{replace:true});return}api(`/student/exams/code/${code}`).then(x=>nav(`/student/exams/${x.id}`,{replace:true})).catch(e=>{setError(e.message);toast(e.message)})},[code,nav]);if(error)return <Shell role="student" title="Exam link"><Card><div className="error">{error}</div><Btn onClick={()=>nav("/student/exams")}>View available exams</Btn></Card></Shell>;return <Shell role="student" title="Opening exam"><Loading/></Shell>}
function ExamReport(){let{id}=useParams(),[d]=useLoad(`/admin/exams/${id}/report`),nav=useNavigate();if(!d)return <Shell role="admin" title="Exam report"><Loading/></Shell>;let s=d.summary;return <Shell role="admin" title={d.exam.title} action={<Btn kind="soft" onClick={()=>nav("/admin/exams")}>Back to exams</Btn>}><div className="stats"><Stat n="Students attended" v={s.attended}/><Stat n="Completed" v={s.completed}/><Stat n="In progress" v={s.in_progress}/><Stat n="Passed" v={s.passed}/><Stat n="Average mark" v={s.average_mark}/></div>{!d.attempts.length?<Card><Empty/></Card>:d.attempts.map(a=><Card className="student-report" key={a.id}><div className="report-student"><div><h3>{a.student}</h3><p>{a.student_id||"No student ID"} · Started {fmt(a.started_at)}</p></div><div><strong>{a.obtained_marks} / {a.total_marks}</strong><Badge>{a.result||a.status}</Badge></div></div><div className="table"><table><thead><tr><th>#</th><th>Question</th><th>Student answer</th><th>Correct answer</th><th>Marks</th></tr></thead><tbody>{a.answers.map((answer,index)=><tr key={answer.question_id}><td>{index+1}</td><td><b>{answer.question}</b><small>{answer.question_type.replaceAll("_"," ")}</small></td><td className={answer.selected_answer==="Not answered"?"muted-answer":""}>{answer.selected_answer}</td><td>{answer.correct_answer}</td><td><b>{answer.marks_obtained} / {answer.total_marks}</b></td></tr>)}</tbody></table></div></Card>)}</Shell>}
function Students(){let[d,reload]=useLoad("/admin/students"),[busy,setBusy]=useState();let verify=async(student,action)=>{setBusy(student.id+action);try{await api(`/admin/students/${student.id}/${action}`,{method:"PUT",body:"{}"});toast(`Student ${action}d successfully`,"success");reload()}catch(error){toast(error.message)}finally{setBusy(null)}};return <Shell role="admin" title="Student verification">{!d?<Loading/>:<Card><h3>Registered students <small>{d.filter(x=>x.status==="PENDING").length} awaiting approval</small></h3><div className="table"><table><thead><tr><th>Student</th><th>ID</th><th>Course</th><th>Student type</th><th>Status</th><th>Verification</th></tr></thead><tbody>{d.map(x=><tr key={x.id}><td><b>{x.name}</b><small>{x.email}</small></td><td>{x.student_id}</td><td>{x.course}</td><td>{x.category}</td><td><Badge>{x.status}</Badge></td><td><div className="verify-actions"><Btn kind="soft" disabled={busy} onClick={()=>verify(x,"approve")}>{x.status==="ACTIVE"?"Approved":"Approve"}</Btn><button className="danger" disabled={busy||x.status==="REJECTED"} onClick={()=>verify(x,"reject")}>Reject</button></div></td></tr>)}</tbody></table></div></Card>}</Shell>}
function InstituteSettings(){let[d,reload]=useLoad("/admin/institute"),[admins,reloadAdmins]=useLoad("/admin/institute/administrators"),[f,setF]=useState({name:"",primary_color:"#4169e1"}),[newAdmin,setNewAdmin]=useState({name:"",email:"",password:""}),[busy,setBusy]=useState(false),logo=useRef();useEffect(()=>{if(d)setF({name:d.name,primary_color:d.primary_color})},[d]);let syncUser=institute=>{let user=JSON.parse(localStorage.user||"null");if(user){user.institute=institute;localStorage.user=JSON.stringify(user)}};let save=async e=>{e.preventDefault();setBusy(true);try{let institute=await api("/admin/institute",{method:"PUT",body:JSON.stringify(f)});syncUser(institute);toast("Institute settings updated","success");reload()}catch(error){toast(error.message)}finally{setBusy(false)}};let uploadLogo=async e=>{let selected=e.target.files[0];if(!selected)return;setBusy(true);try{let body=new FormData();body.append("logo",selected);let response=await fetch(API+"/admin/institute/logo",{method:"POST",headers:{Authorization:`Bearer ${localStorage.token}`},body}),json=await response.json();if(!response.ok)throw Error(json.message);syncUser(json.data);toast("Logo updated","success");reload()}catch(error){toast(error.message)}finally{setBusy(false);e.target.value=""}};let addAdmin=async e=>{e.preventDefault();setBusy(true);try{await api("/admin/institute/administrators",{method:"POST",body:JSON.stringify(newAdmin)});setNewAdmin({name:"",email:"",password:""});toast("Administrator added","success");reloadAdmins()}catch(error){toast(error.message)}finally{setBusy(false)}};let adminAction=async(admin,action)=>{setBusy(true);try{await api(`/admin/institute/administrators/${admin.id}/${action}`,{method:"PUT",body:"{}"});toast(`Administrator ${action}d`,"success");reloadAdmins()}catch(error){toast(error.message)}finally{setBusy(false)}};if(!d)return <Shell role="admin" title="Institute settings"><Loading/></Shell>;let studentUse=Math.min(100,Math.round(100*d.usage.students/d.student_limit)),examUse=Math.min(100,Math.round(100*d.usage.exams/d.exam_limit));return <Shell role="admin" title="Institute settings"><div className="settings-grid"><Card className="brand-settings"><div className="settings-heading"><div><small>BRANDING</small><h2>Workspace identity</h2></div><div className="logo-preview">{d.logo_url?<img src={d.logo_url} alt={`${d.name} logo`}/>:<GraduationCap/>}</div></div><form onSubmit={save}><label>Institute name<input required value={f.name} onChange={e=>setF({...f,name:e.target.value})}/></label><label>Brand colour<div className="color-field"><input type="color" value={f.primary_color} onChange={e=>setF({...f,primary_color:e.target.value})}/><input required pattern="#[0-9a-fA-F]{6}" value={f.primary_color} onChange={e=>setF({...f,primary_color:e.target.value})}/></div></label><div className="settings-actions"><Btn type="button" kind="soft" disabled={busy} onClick={()=>logo.current.click()}><Upload/> Upload logo</Btn><input ref={logo} type="file" accept="image/png,image/jpeg,image/webp" hidden onChange={uploadLogo}/><Btn disabled={busy}>{busy?"Saving…":"Save branding"}</Btn></div></form></Card><Card className="subscription-card"><small>SUBSCRIPTION</small><div className="plan-line"><h2>{d.subscription_plan}</h2><Badge>{d.subscription_status}</Badge></div><p>{d.subscription_ends_at?`Current period ends ${fmt(d.subscription_ends_at)}`:"No expiry date"}</p><Usage label="Students" used={d.usage.students} limit={d.student_limit} percent={studentUse}/><Usage label="Exams" used={d.usage.exams} limit={d.exam_limit} percent={examUse}/><small>{d.usage.administrators} active administrator(s)</small></Card></div><Card className="admin-settings"><div className="settings-heading"><div><small>ACCESS</small><h2>Institute administrators</h2><p>Administrators can manage all students, exams, results, and settings in this institute.</p></div></div><form className="admin-create" onSubmit={addAdmin}><input required placeholder="Full name" value={newAdmin.name} onChange={e=>setNewAdmin({...newAdmin,name:e.target.value})}/><input required type="email" placeholder="Email" value={newAdmin.email} onChange={e=>setNewAdmin({...newAdmin,email:e.target.value})}/><input required minLength="8" type="password" placeholder="Temporary password" value={newAdmin.password} onChange={e=>setNewAdmin({...newAdmin,password:e.target.value})}/><Btn disabled={busy}><Plus/> Add administrator</Btn></form><div className="admin-list">{admins?.map(admin=><div className="admin-row" key={admin.id}><i>{admin.name[0]}</i><span><b>{admin.name}</b><small>{admin.email}</small></span><Badge>{admin.status}</Badge>{admin.status==="ACTIVE"?<button className="danger" disabled={busy} onClick={()=>adminAction(admin,"suspend")}>Suspend</button>:<Btn kind="soft" disabled={busy} onClick={()=>adminAction(admin,"reactivate")}>Reactivate</Btn>}</div>)}</div></Card></Shell>}
const Usage=({label,used,limit,percent})=><div className="usage"><div><span>{label}</span><b>{used} / {limit}</b></div><div className="usage-track"><i style={{width:`${percent}%`}}/></div></div>;
function MonitorAttempt({attempt:a,busy,control}){return <section className="monitor-attempt"><div className="monitor-head"><div><h3>{a.exam_name}</h3><p>Attempt {a.attempt_number} · {a.student_id}</p></div><Badge>{a.connection_status}</Badge></div><div className="monitor-meta"><span><small>Status</small><b>{a.status}</b></span><span><small>Remaining</small><b>{Math.floor(a.remaining_seconds/60)}m {a.remaining_seconds%60}s</b></span><span><small>Progress</small><b>{a.answered}/{a.total_questions} ({a.progress}%)</b></span><span><small>Risk</small><b>{a.risk_score}</b></span><span><small>Refreshes</small><b>{a.refresh_count}</b></span><span><small>Last activity</small><b>{fmt(a.last_activity_at)}</b></span></div>{a.warning&&<div className="warning-box">Warning sent: {a.warning}</div>}<div className="monitor-actions">{a.status==="IN_PROGRESS"&&<Btn disabled={busy} kind="soft" onClick={()=>control(a,"PAUSE")}>Pause</Btn>}{a.status==="PAUSED"&&<Btn disabled={busy} kind="soft" onClick={()=>control(a,"RESUME")}>Resume</Btn>}{["IN_PROGRESS","PAUSED"].includes(a.status)&&<><Btn disabled={busy} kind="soft" onClick={()=>control(a,"ADD_TIME")}>Add time</Btn><Btn disabled={busy} kind="soft" onClick={()=>control(a,"WARN")}>Warn</Btn><Btn disabled={busy} onClick={()=>control(a,"FORCE_SUBMIT")}>Force submit</Btn><button disabled={busy} className="danger" onClick={()=>control(a,"TERMINATE")}>Terminate</button></>}{["COMPLETED","TERMINATED"].includes(a.status)&&<Btn disabled={busy} kind="soft" onClick={()=>control(a,"ALLOW_RETAKE")}>Allow retake</Btn>}</div>{a.events.length>0&&<div className="monitor-evidence"><h4>Evidence ({a.events.length})</h4>{a.events.map(event=><p key={event.id}><b>{event.type.replaceAll("_"," ")}</b> +{event.risk_points} · {fmt(event.created_at)}</p>)}</div>}</section>}
function LiveMonitoring(){let[d,setD]=useState(),[busy,setBusy]=useState();let load=()=>api("/admin/monitoring").then(setD).catch(e=>toast(e.message));useEffect(()=>{load();let timer=setInterval(load,10000);return()=>clearInterval(timer)},[]);let control=async(a,action)=>{let body={action};if(action==="ADD_TIME")body.minutes=Number(prompt("Extra minutes (1–180)","10"));if(action==="WARN")body.message=prompt("Warning message");if(action==="TERMINATE"||action==="ALLOW_RETAKE")body.reason=prompt("Reason");if((action==="ADD_TIME"&&!body.minutes)||(action==="WARN"&&!body.message)||((action==="TERMINATE"||action==="ALLOW_RETAKE")&&!body.reason))return;setBusy(a.id+action);try{await api(`/admin/attempts/${a.id}/control`,{method:"POST",body:JSON.stringify(body)});toast("Attempt updated","success");load()}catch(e){toast(e.message)}finally{setBusy(null)}};let students=d?Object.values(d.attempts.reduce((groups,attempt)=>{let key=attempt.student_id||attempt.student;(groups[key]??={key,name:attempt.student,attempts:[]}).attempts.push(attempt);return groups},{})):[];return <Shell role="admin" title="Live exam monitoring">{!d?<Loading/>:<><div className="stats"><Stat n="Active" v={d.summary.active}/><Stat n="Disconnected" v={d.summary.disconnected}/><Stat n="High risk" v={d.summary.high_risk}/><Stat n="Auto-submitted" v={d.summary.auto_submitted}/></div><div className="monitor-list">{students.length?students.map(student=><details key={student.key} className={`monitor-person risk-${student.attempts.some(a=>a.risk_score>=20)?"high":"normal"}`}><summary><i>{student.name[0]}</i><b>{student.name}</b><ChevronRight/></summary><div className="monitor-person-body">{student.attempts.map(attempt=><MonitorAttempt key={attempt.id} attempt={attempt} busy={busy} control={control}/>)}</div></details>):<Card><Empty/></Card>}</div></>}</Shell>}
function AuditCentre(){let[d]=useLoad("/admin/audit-logs");return <Shell role="admin" title="Audit & security centre">{!d?<Loading/>:<Card><p>{d.pagination.total} recorded events</p><div className="table"><table><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Category</th><th>Entity</th><th>IP address</th><th>Request ID</th></tr></thead><tbody>{d.items.map(row=><tr key={row.id}><td>{fmt(row.created_at)}</td><td>{row.actor}</td><td><b>{row.action.replaceAll("_"," ")}</b></td><td><Badge>{row.category}</Badge></td><td>{row.entity_type||"—"} {row.entity_id||""}</td><td>{row.ip_address||"—"}</td><td><small>{row.request_id||"—"}</small></td></tr>)}</tbody></table></div></Card>}</Shell>}
function AdminHistory(){let[d]=useLoad("/admin/history");return <Shell role="admin" title="Exam history">{!d?<Loading/>:d.map(x=><Card className="history-card"><div><h3>{x.exam.title}</h3><p>{x.exam.exam_category} · {x.attempts.length} attempts</p></div><Badge>{x.exam.status}</Badge><strong>{x.attempts.length?Math.round(x.attempts.reduce((n,a)=>n+a.percentage,0)/x.attempts.length):0}%<small> average</small></strong></Card>)}</Shell>}
function StudentHome(){let[d]=useLoad("/student/dashboard"),nav=useNavigate();if(!d)return <Shell role="student" title="My overview"><Loading/></Shell>;return <Shell role="student" title="My overview"><div className="welcome"><div><small>KEEP MOVING FORWARD</small><h2>Welcome back, {d.profile.name.split(" ")[0]}.</h2><p>{d.profile.course} · {d.profile.student_id}</p></div></div><div className="stats"><Stat n="Completed" v={d.stats.completed}/><Stat n="Pending" v={d.stats.pending}/><Stat n="Average" v={`${d.stats.average_score}%`}/><Stat n="Highest" v={`${d.stats.highest_score}%`}/><Stat n="Pass rate" v={`${d.stats.pass_rate}%`}/></div><div className="twocol"><Card><h3>Available now</h3>{d.upcoming.length?d.upcoming.map(x=><ExamRow x={x} go={()=>nav(`/student/exams/${x.id}`)}/>):<Empty/>}</Card><Card><h3>Recent results</h3>{d.recent.length?d.recent.map(a=><div className="row"><span><b>{a.exam_name}</b><small>{fmt(a.submitted_at)}</small></span><strong>{a.percentage}%</strong><Badge>{a.result}</Badge></div>):<Empty/>}</Card></div></Shell>}
const ExamRow=({x,go})=><div className="exam-row"><i><BookOpen/></i><span><b>{x.title}</b><small>{x.questions} questions · {x.duration} min</small></span><Btn kind="soft" onClick={go}>View</Btn></div>;
function StudentExams(){let[d]=useLoad("/student/exams"),nav=useNavigate();return <Shell role="student" title="Available exams"><div className="intro"><h2>Choose your assessment.</h2><p>Start a new exam or continue an attempt already in progress.</p></div>{!d?<Loading/>:d.length?<div className="exam-grid">{d.map(x=>{let upcoming=new Date(x.start_at)>new Date(),resume=x.attempt_state==="RESUME";return <Card key={x.id} className="exam-card"><i><BookOpen/></i><Badge>{resume?"IN PROGRESS":upcoming?"UPCOMING":"READY"}</Badge><h3>{x.title}</h3><p>{x.description}</p><div><span><Clock/> {x.duration} min</span><span><BookOpen/> {x.questions} questions</span></div><small>{upcoming?`Available ${fmt(x.start_at)}`:`Closes ${fmt(x.end_at)}`}</small><Btn disabled={upcoming} onClick={()=>nav(`/student/exams/${x.id}`)}>{resume?"Resume exam":upcoming?"Not available yet":"Start exam"}</Btn></Card>})}</div>:<Card><div className="empty"><CheckCircle2/><b>You're all caught up</b><span>No new or active exams are available.</span></div></Card>}</Shell>}
function TerminatedAttempt(){let{id}=useParams(),nav=useNavigate(),[d]=useLoad(`/student/attempts/${id}/termination`);if(!d)return <Shell role="student" title="Attempt status"><Loading/></Shell>;return <Shell role="student" title="Attempt status"><div className="termination-page"><span className="termination-icon"><ShieldAlert/></span><small>ATTEMPT CLOSED</small><h1>Exam attempt terminated</h1><p>Your answers were submitted securely, but scores and answer details are unavailable for this attempt.</p><div className="termination-summary"><span><small>Exam</small><b>{d.exam_name}</b></span><span><small>Submitted</small><b>{fmt(d.submitted_at)}</b></span><span><small>Status</small><b>Under administrator review</b></span></div><div className="termination-note"><b>What happens next?</b><p>An administrator can review the recorded evidence and approve a retake when appropriate. Contact your institute if you need assistance.</p></div><div className="termination-actions"><Btn kind="soft" onClick={()=>nav("/student/history")}>View exam history</Btn><Btn onClick={()=>nav("/student/exams")}>Available exams</Btn></div></div></Shell>}
function Attempt(){
  let{id}=useParams(),nav=useNavigate(),[preview,setPreview]=useState(),[agreed,setAgreed]=useState(false),[starting,setStarting]=useState(false),[d,setD]=useState(),[ans,setAns]=useState({}),[i,setI]=useState(0),[left,setLeft]=useState(null),[saveState,setSaveState]=useState("saved"),[lastSavedAt,setLastSavedAt]=useState(null),[online,setOnline]=useState(navigator.onLine),[loadError,setLoadError]=useState(""),[submitting,setSubmitting]=useState(false),pending=useRef(new Map()),saveTimers=useRef(new Map()),offlineSince=useRef(navigator.onLine?null:Date.now());
  let draftKey=d?`exam_draft_${d.attempt_id}`:null;
  const persistPending=()=>{if(!draftKey)return;let values=Object.fromEntries(pending.current);values&&Object.keys(values).length?localStorage.setItem(draftKey,JSON.stringify(values)):localStorage.removeItem(draftKey)};
  const saveOne=async(questionId,value)=>{if(!d||!navigator.onLine)return false;let error;for(let retry=0;retry<3;retry++){try{let result=await api(`/student/attempts/${d.attempt_id}/answers`,{method:"POST",body:JSON.stringify({question_id:Number(questionId),answer:value})});if(result.completed){localStorage.removeItem(draftKey);nav(`/student/results/${result.result_id}`,{replace:true});return true}if(pending.current.get(String(questionId))===value)pending.current.delete(String(questionId));persistPending();setLastSavedAt(new Date());setSaveState(pending.current.size?"queued":"saved");return true}catch(e){error=e;if(retry<2&&navigator.onLine)await new Promise(resolve=>setTimeout(resolve,600*(retry+1)))}}setSaveState("error");if(error&&navigator.onLine)toast(`Answer queued locally: ${error.message}`,"warning");return false};
  const flushQueued=async()=>{saveTimers.current.forEach(timer=>clearTimeout(timer));saveTimers.current.clear();if(!navigator.onLine){setSaveState("queued");return false}let entries=[...pending.current.entries()];if(!entries.length){setSaveState("saved");return true}setSaveState("saving");for(let[questionId,value]of entries)await saveOne(questionId,value);let complete=pending.current.size===0;setSaveState(complete?"saved":"error");return complete};
  const queueSave=(questionId,value,delay=0)=>{let key=String(questionId);setAns(current=>({...current,[key]:value}));pending.current.set(key,value);persistPending();setSaveState(navigator.onLine?"saving":"queued");let existing=saveTimers.current.get(key);if(existing)clearTimeout(existing);let timer=setTimeout(()=>{saveTimers.current.delete(key);saveOne(key,value)},delay);saveTimers.current.set(key,timer)};
  useEffect(()=>{api(`/student/exams/${id}`).then(setPreview).catch(e=>{setLoadError(e.message);toast(e.message)})},[id]);
  useEffect(()=>{if(!d)return;let recovered={};try{recovered=JSON.parse(localStorage.getItem(draftKey)||"{}")}catch{}pending.current=new Map(Object.entries(recovered));setAns({...d.saved_answers,...recovered});if(pending.current.size){setSaveState(navigator.onLine?"saving":"queued");setTimeout(flushQueued,0)}setLeft(Math.max(0,Math.ceil((new Date(d.expires_at)-Date.now())/1000)))},[d?.attempt_id]);
  useEffect(()=>{if(!d)return;let update=()=>setLeft(Math.max(0,Math.ceil((new Date(d.expires_at)-Date.now())/1000)));update();let timer=setInterval(update,1000);return()=>clearInterval(timer)},[d]);
  useEffect(()=>{let connected=()=>{let seconds=offlineSince.current?Math.round((Date.now()-offlineSince.current)/1000):0;offlineSince.current=null;setOnline(true);if(d&&seconds>=30)api(`/student/attempts/${d.attempt_id}/events`,{method:"POST",body:JSON.stringify({event_type:"PROLONGED_DISCONNECTION",details:{offline_seconds:seconds}})}).catch(()=>{});flushQueued()},disconnected=()=>{offlineSince.current=Date.now();setOnline(false);if(pending.current.size)setSaveState("queued")};window.addEventListener("online",connected);window.addEventListener("offline",disconnected);return()=>{window.removeEventListener("online",connected);window.removeEventListener("offline",disconnected)}},[d?.attempt_id]);
  useEffect(()=>{if(!d||submitting)return;let warn=e=>{if(pending.current.size||saveState==="saving"){e.preventDefault();e.returnValue=""}};window.addEventListener("beforeunload",warn);return()=>window.removeEventListener("beforeunload",warn)},[d,submitting,saveState]);
  useEffect(()=>()=>{saveTimers.current.forEach(timer=>clearTimeout(timer))},[]);
  const begin=async()=>{if(!agreed||starting)return;setStarting(true);try{if(document.fullscreenEnabled&&!document.fullscreenElement)await document.documentElement.requestFullscreen().catch(()=>{});let attempt=await api(`/student/exams/${id}/start`,{method:"POST",body:JSON.stringify({session_id:sessionStorage.exam_session_id})});if(attempt.completed)return nav(`/student/results/${attempt.result_id}`,{replace:true});if(attempt.terminated)return nav(`/student/terminated/${attempt.attempt_id}`,{replace:true});setD(attempt)}catch(e){toast(e.message);setStarting(false)}};
  const finish=async(force=false)=>{if(submitting)return;if(!force&&!confirm("Submit this exam? You cannot change your answers afterward."))return;if(pending.current.size)toast("Please wait while your latest answers finish syncing.","warning");setSubmitting(true);let synced=await flushQueued();if(!synced){setSubmitting(false);toast(online?"Some answers are still syncing. Please wait and try again.":"You are offline. Reconnect before submitting.","warning");return}try{let result=await api(`/student/attempts/${d.attempt_id}/submit`,{method:"POST"});localStorage.removeItem(draftKey);nav(`/student/results/${result.id}`,{replace:true})}catch(e){setSubmitting(false);toast(e.message)}};
  useEffect(()=>{if(d&&left===0)finish(true)},[left,d]);
  if(loadError)return <Shell role="student" title="Exam"><Card><div className="error">{loadError}</div><Btn onClick={()=>nav("/student/exams")}>Back to exams</Btn></Card></Shell>;
  if(!preview)return <Shell role="student" title="Exam"><Loading/></Shell>;
  if(!d)return <Shell role="student" title={preview.title}><div className="exam-brief"><div className="brief-hero"><span><ShieldAlert/></span><div><small>BEFORE YOU BEGIN</small><h2>Read the exam instructions carefully</h2><p>The timer starts only after you select “Begin exam”.</p></div></div><div className="brief-facts"><div><Clock/><span><small>Duration</small><b>{preview.duration} minutes</b></span></div><div><BookOpen/><span><small>Questions</small><b>{preview.questions} questions</b></span></div></div><div className="instruction-list"><section><b>Tab-switch policy</b><p>Your first tab switch gives one warning. A second switch terminates and automatically submits the exam.</p></section><section><b>Internet and browser</b><p>Use a stable connection and a current version of Chrome, Edge, Firefox, or Safari. Keep this page open.</p></section><section><b>Full-screen recommendation</b><p>Full screen reduces distractions and accidental tab switching. Your browser may ask for permission.</p></section><section><b>Answer protection</b><p>Answers save automatically. Unsaved changes are kept on this device and retried after reconnection.</p></section></div><label className="exam-consent"><input type="checkbox" checked={agreed} onChange={e=>setAgreed(e.target.checked)}/><span><b>I understand and agree</b><small>I have read the rules and am ready to begin.</small></span></label><div className="brief-actions"><Btn kind="soft" onClick={()=>nav("/student/exams")}>Back</Btn><Btn disabled={!agreed||starting} onClick={begin}>{starting?"Starting…":"Begin exam"} <ChevronRight/></Btn></div></div></Shell>;
  let q=d.exam.question_list[i];
  const toggle=optionId=>{let current=Array.isArray(ans[q.id])?ans[q.id]:[],value=current.includes(optionId)?current.filter(x=>x!==optionId):[...current,optionId];queueSave(q.id,value)};
  const answered=value=>Array.isArray(value)?value.length>0:String(value??"").trim().length>0;
  let syncLabel=!online?"Offline — answers queued":saveState==="saving"?"Saving…":saveState==="queued"?"Waiting to sync":saveState==="error"?"Sync failed":lastSavedAt?`Saved ${lastSavedAt.toLocaleTimeString([],{hour:"2-digit",minute:"2-digit",second:"2-digit"})}`:"All answers saved";
  return <Shell role="student" title={d.exam.title}>{!online&&<div className="offline-banner" role="status"><ShieldAlert/><span><b>You are offline</b><small>Your timer continues and answers are safely queued on this device.</small></span></div>}<div className="timer"><span>Question {i+1} of {d.exam.questions}<small className={`save-state ${saveState} ${!online?"offline":""}`}>{syncLabel}</small></span><b><Clock/> {String(Math.floor((left||0)/60)).padStart(2,"0")}:{String((left||0)%60).padStart(2,"0")}</b></div><div className="attempt"><Card className="question"><small>QUESTION {i+1} · {q.marks} MARKS · {q.type.replaceAll("_"," ")}</small><h2>{q.text}</h2>{(q.type==="SINGLE"||q.type==="TRUE_FALSE")&&<div className="choices">{q.options.map((o,j)=><button key={o.id} className={ans[q.id]===o.id?"selected":""} onClick={()=>queueSave(q.id,o.id)}><i>{String.fromCharCode(65+j)}</i>{o.text}</button>)}</div>}{q.type==="MULTIPLE"&&<div className="choices multiple">{q.options.map((o,j)=><button key={o.id} className={(ans[q.id]||[]).includes(o.id)?"selected":""} onClick={()=>toggle(o.id)}><i>{(ans[q.id]||[]).includes(o.id)?"✓":String.fromCharCode(65+j)}</i>{o.text}</button>)}</div>}{q.type==="SHORT_ANSWER"&&<input className="text-answer" value={ans[q.id]||""} onChange={e=>queueSave(q.id,e.target.value,800)} placeholder="Type your answer"/>}{q.type==="PARAGRAPH"&&<textarea className="paragraph-answer" value={ans[q.id]||""} onChange={e=>queueSave(q.id,e.target.value,800)} placeholder="Write your detailed answer"/>}<footer><Btn kind="soft" disabled={!i} onClick={()=>setI(i-1)}>Previous</Btn>{i<d.exam.questions-1?<Btn onClick={()=>setI(i+1)}>Next</Btn>:<Btn disabled={submitting} onClick={()=>finish(false)}>{submitting?"Syncing & submitting…":"Submit exam"}</Btn>}</footer></Card><Card className="navigator"><h3>Questions</h3><div>{d.exam.question_list.map((item,j)=><button key={item.id} className={`${j===i?"current":""} ${answered(ans[item.id])?"answered":""}`} onClick={()=>setI(j)}>{j+1}</button>)}</div></Card></div></Shell>
}
function StudentHistory(){let[d]=useLoad("/student/history"),nav=useNavigate();return <Shell role="student" title="Exam history">{!d?<Loading/>:<Card><div className="table"><table><thead><tr><th>Exam</th><th>Date</th><th>Score</th><th>Result</th><th></th></tr></thead><tbody>{d.map(a=>{let terminated=a.status==="TERMINATED";return <tr key={a.id}><td><b>{a.exam_name}</b><small>{a.exam_category}</small></td><td>{fmt(a.submitted_at||a.started_at)}</td><td>{terminated?"Hidden":`${a.percentage}%`}</td><td><Badge>{terminated?"TERMINATED":a.result||a.status}</Badge></td><td><Btn kind="soft" onClick={()=>nav(terminated?`/student/terminated/${a.id}`:`/student/results/${a.id}`)}>{terminated?"View status":"Details"}</Btn></td></tr>})}</tbody></table></div></Card>}</Shell>}
function Result(){let{id}=useParams(),nav=useNavigate(),[d]=useLoad(`/student/results/${id}`);if(!d)return <Shell role="student" title="Result"><Loading/></Shell>;let passed=d.result==="PASS";return <Shell role="student" title="Exam result"><div className={`result ${d.result.toLowerCase()}`}><CheckCircle2/><small>ASSESSMENT COMPLETE</small><h2>{d.percentage}%</h2><h3>{passed?"Congratulations, you passed":"Keep going — this attempt did not pass"}</h3><p>{d.obtained_marks} out of {d.total_marks} marks</p><Btn kind="soft" onClick={()=>nav("/student/exams")}>Back to available exams</Btn></div><div className="stats result-stats"><Stat n="Correct" v={d.correct_answers}/><Stat n="Incorrect" v={d.wrong_answers}/><Stat n="Unanswered" v={d.unanswered_questions}/><Stat n="Time taken" v={`${Math.ceil(d.time_taken/60)} min`}/></div><div className="review-heading"><div><small>DETAILED REVIEW</small><h2>Answer review</h2></div><p>Compare your responses with the correct answers.</p></div>{d.answers.map((a,i)=><Card key={i} className={`answer ${a.is_correct?"correct":"wrong"}`}><Badge>{a.is_correct?"Correct":"Incorrect"}</Badge><h3>{i+1}. {a.question}</h3><p>Correct answer: <b>{a.correct_answer.join(", ")}</b></p><strong>{a.marks} marks earned</strong></Card>)}</Shell>}
export default function App(){return <><ToastHost/><Routes><Route path="/" element={<Navigate to="/login/student"/>}/><Route path="/login/admin" element={<Login role="admin"/>}/><Route path="/login/student" element={<Login role="student"/>}/><Route path="/register" element={<Register/>}/><Route path="/onboard" element={<InstituteOnboarding/>}/><Route path="/forgot-password" element={<ForgotPassword/>}/><Route path="/reset-password/:token" element={<ResetPassword/>}/><Route path="/verify-email/:token" element={<VerifyEmail/>}/><Route path="/resend-verification" element={<ResendVerification/>}/><Route path="/exam/:code" element={<ExamLink/>}/><Route path="/admin" element={<AdminHome/>}/><Route path="/admin/monitoring" element={<LiveMonitoring/>}/><Route path="/admin/audit" element={<AuditCentre/>}/><Route path="/admin/exams" element={<AdminExams/>}/><Route path="/admin/exams/new" element={<NewExam/>}/><Route path="/admin/exams/:id/edit" element={<NewExam/>}/><Route path="/admin/exams/:id/report" element={<ExamReport/>}/><Route path="/admin/students" element={<Students/>}/><Route path="/admin/history" element={<AdminHistory/>}/><Route path="/admin/settings" element={<InstituteSettings/>}/><Route path="/student" element={<StudentHome/>}/><Route path="/student/exams" element={<StudentExams/>}/><Route path="/student/exams/:id" element={<Attempt/>}/><Route path="/student/history" element={<StudentHistory/>}/><Route path="/student/results/:id" element={<Result/>}/><Route path="/student/terminated/:id" element={<TerminatedAttempt/>}/><Route path="*" element={<Navigate to="/"/>}/></Routes></>}
